window.GameEffects=(()=>{let context;function audio(){context??=new AudioContext();return context}function play(name='click'){const options={click:[540,.05,'sine'],move:[330,.09,'triangle'],flip:[180,.12,'square'],draw:[260,.1,'sine'],success:[660,.18,'triangle'],error:[130,.16,'sawtooth'],win:[784,.35,'sine']}[name]||[440,.08,'sine'];try{const ctx=audio(),oscillator=ctx.createOscillator(),gain=ctx.createGain();oscillator.type=options[2];oscillator.frequency.setValueAtTime(options[0],ctx.currentTime);if(name==='win'||name==='success')oscillator.frequency.exponentialRampToValueAtTime(options[0]*1.5,ctx.currentTime+options[1]);gain.gain.setValueAtTime(.09,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+options[1]);oscillator.connect(gain).connect(ctx.destination);oscillator.start();oscillator.stop(ctx.currentTime+options[1])}catch{}}function animate(element,name='pulse'){if(!element)return;element.classList.remove(`fx-${name}`);void element.offsetWidth;element.classList.add(`fx-${name}`)}const style=document.createElement('style');style.textContent='.fx-pulse{animation:fx-pulse .28s ease-out}.fx-shake{animation:fx-shake .32s ease}.fx-flip{animation:fx-flip .36s ease-in-out}@keyframes fx-pulse{50%{transform:scale(1.08)}}@keyframes fx-shake{25%{transform:translateX(-5px)}75%{transform:translateX(5px)}}@keyframes fx-flip{50%{transform:scaleY(.05)}}';document.head.appendChild(style);return{play,animate}})();
